<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Classify/cat_field',array('cid'=>$now_category['cid']))}" class="on">字段列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Merchant/add_field')}','添加字段',600,400,true,false,false,addbtn,'add',true);">添加字段</a>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<!--col/-->							<col/>							<col/>							<col/>							<!--col/-->							<!--col width="180" align="center"/-->						</colgroup>						<thead>							<tr>								<!--th>排序</th-->								<th>名称</th>								<th>短标记(url)</th>								<th>类型</th>								<th>筛选字段</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<!--td>{pigcms{$vo.sort}</td-->										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$vo.url}</td>										<td>											<if condition="$vo['type'] eq '5'">											多文本框											<elseif condition="$vo['type'] eq '4'"/>											下拉框											<elseif condition="$vo['type'] eq '3'"/>											复选框											<elseif condition="$vo['type'] eq '2'"/>											单选框											<elseif condition="$vo['type'] eq '1'"/>											单文本框											<else/>											未知											</if>										</td>										<td><if condition="$vo['isfilter'] eq 1"> 是 <else/> 否 </if></td>										<td class="textcenter"><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Merchant/edit_field',array('id'=>$vo['id']))}','编辑字段',600,400,true,false,false,editbtn,'edit',true);">编辑</a>&nbsp;|&nbsp;										<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Merchant/field_del')}">删除</a>										</td>										<!--td><if condition="$vo['status'] eq 1"><font color="green">显示</font><else/><font color="red">隐藏</font></if></td-->										<!--td class="textcenter"><a href="javascript:void(0);" class="delete_row" parameter="cat_id={pigcms{$vo.cat_id}" url="{pigcms{:U('Classify/cat_del')}">删除</a></td-->									</tr>								</volist>							<else/>								<tr><td class="textcenter red" colspan="5">商品属性字段 列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>